import React, { useCallback, useEffect, useState } from "react";
import { PDFDocument } from "pdf-lib";
import * as pdfjsLib from "pdfjs-dist/webpack";
import "./style.css";
import MeeshoLogo from "../../assets/Meesho.png";
const MeeshoCrop = () => {
  const [file, setFile] = useState(null);

  const handleFileChange = (event) => {
    if (event.target.files && event.target.files[0]) {
      setFile(event.target.files[0]);
    }
  };

  const modifyPdf = useCallback(async () => {
    if (!file) {
      alert("Please upload a PDF file first.");
      return;
    }

    try {
      const fileBuffer = await file.arrayBuffer();
      const pdfDoc = await PDFDocument.load(fileBuffer);
      const pages = pdfDoc.getPages();
      const pdfjsDoc = await pdfjsLib.getDocument(fileBuffer).promise;
      const pageCount = pdfjsDoc.numPages;
      let removePageCount = 0;
      for (let i = 1; i <= pageCount; i++) {
        const page = await pdfjsDoc.getPage(i);
        const textContent = await page.getTextContent();

        const hei = textContent.items.find((item, i) => {
          return item?.str?.toLowerCase() === "tax invoice";
        });
        const isCustomerAddress = textContent.items.find((item, i) => {
          return item?.str === "Customer Address";
        });
        if (hei && isCustomerAddress) {
          const { width, height } = pages[i - 1].getSize();
          pages[i - 1].setCropBox(0, hei.transform[5] - 5, width, height);
        } else {
          removePageCount++;
          pdfDoc.removePage(i - removePageCount);
        }
      }
      const modifiedPdfBytes = await pdfDoc.save();
      const blob = new Blob([modifiedPdfBytes], { type: "application/pdf" });
      const pdfUrl = URL.createObjectURL(blob);

      // Open the modified PDF in a new tab
      const newTab = window.open();
      if (newTab) {
        newTab.location.href = pdfUrl;
      }
    } catch (error) {
      console.error("Error modifying the PDF:", error);
      alert("An error occurred while modifying the PDF. Please try again.");
    }
  }, [file]);

  useEffect(() => {
    (window.adsbygoogle = window.adsbygoogle || []).push({});
  }, []);

  return (
    <div className="container">
      <ins
        className="adsbygoogle"
        style={{ display: "block" }}
        data-ad-client="ca-pub-3570575479522194"
        data-ad-slot="1288221466"
        data-ad-format="auto"
        data-full-width-responsive="true"
      ></ins>
      <h1 className="title">📦 Meesho Shipping Label Crop Tool 🚀</h1>
      <p className="description">
        Effortlessly manage your Meesho shipping labels with just a few clicks!
        🖱️✨ Upload your Meesho label file, hit the{" "}
        <strong>"Prepare Shipping Labels"</strong>
        button, and let the magic happen! 🪄 This tool will automatically crop
        and generate shipping labels for each order, saving you tons of time. ⏳
      </p>

      <div>
        <div className="input-container">
          <img src={MeeshoLogo} alt="Meesho Logo" className="logo" />
          <input
            type="file"
            accept="application/pdf"
            onChange={handleFileChange}
            className="file-input"
          />
        </div>
        <p style={{ margin: "0px 0px 20px 0px" }} className="file-instruction">
          📂 Upload your PDF file here!
        </p>
      </div>

      <button onClick={modifyPdf} className="button">
        ✂️ &nbsp; Prepare Shipping Labels
      </button>

      <p className="note">
        🔄 Say goodbye to manual cropping and hello to a smoother shipping
        process! 📬💌
      </p>

      <p className="extra-info">
        🌟 Pro Tip: Double-check your uploaded file before processing for the
        best results. 😉 Happy shipping! 🚚✨
      </p>
    </div>
  );
};

export default MeeshoCrop;
